void Config::applyLine(char* line) {
  // '#' only starts a comment at the beginning of a line: passwords may contain it.
  const char* first = line + strspn(line, " \t");
  if (*first == '#') return;
  char* eq = strchr(line, '=');
  if (!eq) return;
  *eq = '\0';
  char* key = line;
  char* value = eq + 1;
  trim(key);
  trim(value);
  // Empty values (as in the template) keep what's already set, e.g. baked in at
  // flash time. "journal_subfolder = /" clears it back to the top level.
  if (!value[0]) return;
  if (strcmp(key, "wifi_ssid") == 0) copyField(wifiSsid, sizeof(wifiSsid), value);
  else if (strcmp(key, "wifi_password") == 0) copyField(wifiPassword, sizeof(wifiPassword), value);
  else if (strcmp(key, "timezone") == 0) copyField(timezone, sizeof(timezone), value);
  else if (strcmp(key, "notes_folder") == 0) copyField(notesFolder, sizeof(notesFolder), value);
  else if (strcmp(key, "journal_subfolder") == 0) copyField(journalSubfolder, sizeof(journalSubfolder), value);
  else if (strcmp(key, "repo_url") == 0 || strcmp(key, "github_repo") == 0) copyField(repoUrl, sizeof(repoUrl), value);
  else if (strcmp(key, "branch") == 0 || strcmp(key, "github_branch") == 0) copyField(branch, sizeof(branch), value);
  else if (strcmp(key, "git_token") == 0 || strcmp(key, "github_token") == 0) copyField(token, sizeof(token), value);
  else if (strcmp(key, "location") == 0) locationFromPhone = strcmp(value, "phone") == 0;
  else if (strcmp(key, "location_every") == 0) locationEveryMin = static_cast<uint16_t>(constrain(atoi(value), 0, 1440));
  else if (strcmp(key, "writing_stats") == 0) writingStats = strcmp(value, "off") != 0;
  else if (strcmp(key, "prompts") == 0) prompts = strcmp(value, "off") == 0 ? 0 : strcmp(value, "always") == 0 ? 2 : 1;
}

namespace {

constexpr const char* kPrefsNs = "inkcfg";
constexpr const char* kPrefsKey = "cfg";
constexpr size_t kStoreMax = 2048;

// Calls fn(line) for each '\n'-separated line of `text` (lines are copied into
// a writable buffer first).
template <typename Fn>
void forEachLine(const char* text, Fn fn) {
  char line[256];
  const char* p = text;
  while (*p) {
    const char* nl = strchr(p, '\n');
    const size_t len = nl ? static_cast<size_t>(nl - p) : strlen(p);
    const size_t n = len < sizeof(line) - 1 ? len : sizeof(line) - 1;
    memcpy(line, p, n);
    line[n] = '\0';
    fn(line);
    p += len + (nl ? 1 : 0);
  }
}

// Key of a "key = value" line, trimmed, into `out` (empty for comments etc).
void lineKey(const char* line, char* out, size_t outsz) {
  out[0] = '\0';
  const char* first = line + strspn(line, " \t");
  const char* eq = strchr(first, '=');
  if (*first == '#' || !eq) return;
  size_t n = static_cast<size_t>(eq - first);
  while (n > 0 && (first[n - 1] == ' ' || first[n - 1] == '\t')) --n;
  if (n >= outsz) return;
  memcpy(out, first, n);
  out[n] = '\0';
}

bool lineHasValue(const char* line) {
  const char* eq = strchr(line, '=');
  return eq && eq[1 + strspn(eq + 1, " \t\r")] != '\0';
}

String readStored() {
  Preferences prefs;
  if (!prefs.begin(kPrefsNs, true)) return String();
  String s = prefs.getString(kPrefsKey, "");
  prefs.end();
  return s;
}

}  // namespace

bool Config::load() {
  *this = Config();

  // Values baked in at flash time, then those saved on the device.
  forEachLine(kFlashConfig, [this](char* line) { applyLine(line); });
  const String stored = readStored();
  forEachLine(stored.c_str(), [this](char* line) { applyLine(line); });

  // The SD card file overrides them.
  char line[256];
  FsFile f = SdMan.ready() ? SdMan.open(kPath, O_RDONLY) : FsFile();
  const bool found = static_cast<bool>(f);
  while (f && f.available()) {
    int n = f.fgets(line, sizeof(line));
    if (n <= 0) break;
    if (line[n - 1] == '\n') line[n - 1] = '\0';
    applyLine(line);
  }
  if (f) f.close();

  normalizeFolder(notesFolder, true);
  normalizeFolder(journalSubfolder, false);
  if (!syncutil::parseRepoUrl(repoUrl, repoHost, sizeof(repoHost), repo, sizeof(repo))) {
    repoHost[0] = repo[0] = '\0';
  }
  return found;
}

bool Config::writeTemplateIfMissing() const {
  if (SdMan.exists(kPath)) return false;
  FsFile f = SdMan.open(kPath, O_WRONLY | O_CREAT | O_TRUNC);
  if (!f) return false;
  f.write(reinterpret_cast<const uint8_t*>(kTemplate), sizeof(kTemplate) - 1);
  f.close();
  return true;
}

bool Config::isKnownKey(const char* key) {
  static const char* kKeys[] = {"wifi_ssid", "wifi_password", "timezone",     "notes_folder",  "journal_subfolder",
                                "repo_url",  "branch",        "git_token",    "github_repo",   "github_branch",
                                "github_token", "location",    "location_every", "writing_stats", "prompts"};
  for (const char* k : kKeys) {
    if (strcmp(k, key) == 0) return true;
  }
  return false;
}

bool Config::storeOnDevice(const char* lines) {
  const bool ok = storeLines(lines);
  load();
  return ok;
}

bool Config::storeLines(const char* lines) {
  const String stored = readStored();
  String merged;
  // Keep stored lines whose key isn't being set now...
  forEachLine(stored.c_str(), [&](char* line) {
    char key[32];
    lineKey(line, key, sizeof(key));
    if (!key[0]) return;
    bool replaced = false;
    forEachLine(lines, [&](char* incoming) {
      char k[32];
      lineKey(incoming, k, sizeof(k));
      if (strcmp(k, key) == 0) replaced = true;
    });
    if (!replaced) {
      merged += line;
      merged += '\n';
    }
  });
  // ...then add the new ones (an empty value just drops the key).
  forEachLine(lines, [&](char* line) {
    char key[32];
    lineKey(line, key, sizeof(key));
    if (key[0] && lineHasValue(line)) {
      merged += line;
      merged += '\n';
    }
  });
  if (merged.length() > kStoreMax) return false;

  Preferences prefs;
  if (!prefs.begin(kPrefsNs, false)) return false;
  bool ok = true;
  if (merged.length() == 0) {
    prefs.remove(kPrefsKey);
  } else {
    ok = prefs.putString(kPrefsKey, merged) == merged.length();
  }
  prefs.end();
  return ok;
}

bool Config::sdOverrides(const char* key) const {
  if (!SdMan.ready()) return false;
  FsFile f = SdMan.open(kPath, O_RDONLY);
  if (!f) return false;
  bool found = false;
  char line[256];
  while (!found && f.available()) {
    int n = f.fgets(line, sizeof(line));
    if (n <= 0) break;
    if (line[n - 1] == '\n') line[n - 1] = '\0';
    char k[32];
    lineKey(line, k, sizeof(k));
    found = strcmp(k, key) == 0 && lineHasValue(line);
  }
  f.close();
  return found;
}
